import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"Terminal y Linux — La caja de herramientas Unix","description":"WSL2, scripting de shell, SSH, systemd y la caja de herramientas Unix — el entorno donde realmente ocurre todo mi trabajo.","frontmatter":{"title":"Terminal y Linux — La caja de herramientas Unix","description":"WSL2, scripting de shell, SSH, systemd y la caja de herramientas Unix — el entorno donde realmente ocurre todo mi trabajo."},"headers":[],"relativePath":"es/skills/terminal/index.md","filePath":"es/skills/terminal/index.md"}`),a={name:`es/skills/terminal/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="terminal-y-linux-—-la-caja-de-herramientas-unix" tabindex="-1">Terminal y Linux — La caja de herramientas Unix <a class="header-anchor" href="#terminal-y-linux-—-la-caja-de-herramientas-unix" aria-label="Permalink to “Terminal y Linux — La caja de herramientas Unix”">​</a></h1><p>Mi entorno de trabajo principal es la terminal — normalmente WSL2 en Windows, que me da ambos mundos, o una máquina Linux pelada para servicios. La fluidez aquí no es nostalgia; es palanca. Cada herramienta que uso, incluido cada agente, termina moviendo los mismos primitivos Unix.</p><h2 id="uso-diario" tabindex="-1">Uso diario <a class="header-anchor" href="#uso-diario" aria-label="Permalink to “Uso diario”">​</a></h2><table tabindex="0"><thead><tr><th>Área</th><th>Herramientas</th></tr></thead><tbody><tr><td>Shell</td><td>bash/zsh, pipes, jq, one-liners de awk/sed, fzf</td></tr><tr><td>Remoto</td><td>Claves y agentes SSH, sesiones tmux, port forwarding</td></tr><tr><td>Servicios</td><td>unidades systemd, cron, rotación de logs</td></tr><tr><td>Contenedores</td><td>Docker, compose, imágenes mínimas</td></tr><tr><td>Inspección</td><td>htop, ss/netstat, strace, journalctl</td></tr></tbody></table><p>De aquí vino la filosofía de <a href="/Usf/es/projects/netpilot/">NetPilot</a>: las mejores herramientas de terminal hacen un trabajo, siguen siendo rápidas y se componen entre sí. Sostengo mis propias herramientas — y el output de mis agentes — al mismo estándar. Un comando que no puede pasarse por pipe es un comando que reescribiré.</p>`,5)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};